mapper.select:
SELECT e.id AS equipment_id, e.asset_code, e.name AS equipment_name,
       COUNT(*) AS work_order_count
FROM work_orders w
INNER JOIN equipment e ON e.tenant_id = w.tenant_id AND e.id = w.equipment_id
WHERE w.tenant_id = #{tenantId}
  AND w.created_at >= #{startTime}
  AND w.created_at < #{endTime}
GROUP BY e.id, e.asset_code, e.name
ORDER BY work_order_count DESC, e.id ASC
LIMIT #{limit}
